23	template <MaskPattern Pattern>
24	PTO_INTERNAL constexpr unsigned Int64MaskPatternOffset()
25	{
26	    if constexpr (Pattern == MaskPattern::P1010 || Pattern == MaskPattern::P0010)
27	        return 1;
28	    if constexpr (Pattern == MaskPattern::P0100)
29	        return 2;
30	    if constexpr (Pattern == MaskPattern::P1000)
31	        return 3;
32	    return 0;
33	}
