43	PTO_INTERNAL void Int64AddRegs(
44	    vector_s32& dstLow, vector_s32& dstHigh, vector_s32& lhsLow, vector_s32& lhsHigh, vector_s32& rhsLow,
45	    vector_s32& rhsHigh, MaskReg& mask)
46	{
47	    MaskReg carry, carryOut;
48	    vaddc(carry, dstLow, lhsLow, rhsLow, mask);
49	    vaddcs(carryOut, dstHigh, lhsHigh, rhsHigh, carry, mask);
50	}
