52	PTO_INTERNAL void Int64SubRegs(
53	    vector_s32& dstLow, vector_s32& dstHigh, vector_s32& lhsLow, vector_s32& lhsHigh, vector_s32& rhsLow,
54	    vector_s32& rhsHigh, MaskReg& mask)
55	{
56	    MaskReg carry, carryOut;
57	    vsubc(carry, dstLow, lhsLow, rhsLow, mask);
58	    vsubcs(carryOut, dstHigh, lhsHigh, rhsHigh, carry, mask);
59	}
