61	PTO_INTERNAL void Int64MulRegs(
62	    vector_s32& dstLow, vector_s32& dstHigh, vector_s32& lhsLow, vector_s32& lhsHigh, vector_s32& rhsLow,
63	    vector_s32& rhsHigh, MaskReg& mask)
64	{
65	    vmull((vector_u32&)dstLow, (vector_u32&)dstHigh, (vector_u32&)lhsLow, (vector_u32&)rhsLow, mask);
66	    vmula(dstHigh, lhsLow, rhsHigh, mask, MODE_ZEROING);
67	    vmula(dstHigh, lhsHigh, rhsLow, mask, MODE_ZEROING);
68	}
