70	PTO_INTERNAL void Int64SelectRegs(
71	    vector_s32& dstLow, vector_s32& dstHigh, vector_s32& lhsLow, vector_s32& lhsHigh, vector_s32& rhsLow,
72	    vector_s32& rhsHigh, MaskReg& mask)
73	{
74	    vsel(dstLow, lhsLow, rhsLow, mask);
75	    vsel(dstHigh, lhsHigh, rhsHigh, mask);
