78	PTO_INTERNAL void Int64CompareEqRegs(
79	    MaskReg& dst, vector_s32& lhsLow, vector_s32& lhsHigh, vector_s32& rhsLow, vector_s32& rhsHigh, MaskReg& mask)
80	{
81	    MaskReg lowEq, highEq;
82	    vcmp_eq(lowEq, (vector_u32&)lhsLow, (vector_u32&)rhsLow, mask);
83	    vcmp_eq(highEq, (vector_u32&)lhsHigh, (vector_u32&)rhsHigh, mask);
84	    pand(dst, lowEq, highEq, mask);
85	}
