97	PTO_INTERNAL void Int64AbsRegs(
98	    vector_s32& dstLow, vector_s32& dstHigh, vector_s32& srcLow, vector_s32& srcHigh, MaskReg& mask)
99	{
100	    vector_s32 zero, negLow, negHigh;
101	    vbr(zero, 0);
102	    MaskReg negative, carry, carryOut;
103	    vcmp_lt(negative, srcHigh, zero, mask);
104	    vsubc(carry, negLow, zero, srcLow, negative);
105	    vsubcs(carryOut, negHigh, zero, srcHigh, carry, negative);
106	    vsel(dstLow, negLow, srcLow, negative);
107	    vsel(dstHigh, negHigh, srcHigh, negative);
108	}
