110	PTO_INTERNAL void Int64NotRegs(vector_s32& low, vector_s32& high, MaskReg& mask)
111	{
112	    vnot((vector_u32&)low, (vector_u32&)low, mask, MODE_ZEROING);
113	    vnot((vector_u32&)high, (vector_u32&)high, mask, MODE_ZEROING);
114	}
