124	template <typename Op, typename T, unsigned ElementsPerRepeat, unsigned BlockSizeElem>
125	PTO_INTERNAL void TBinOps_1D_NoPostUpdate(
126	    __ubuf__ T* dstPtr, __ubuf__ T* src0Ptr, __ubuf__ T* src1Ptr, unsigned validRows, unsigned validCols)
127	{
128	    uint16_t repeatTimes = CeilDivision(validRows * validCols, ElementsPerRepeat);
129	    __VEC_SCOPE__
130	    {
131	        RegTensor<T> vreg0, vreg1, vreg2;
132	        MaskReg preg;
133	
134	        constexpr auto distValue =
135	            std::integral_constant<::DistVST, static_cast<::DistVST>(GetDistVst<T, DistVST::DIST_NORM>())>();
136	        unsigned sreg = validRows * validCols;
137	        for (uint16_t i = 0; i < (uint16_t)repeatTimes; ++i) {
138	            preg = CreatePredicate<T>(sreg);
139	            vlds(vreg0, src0Ptr, i * ElementsPerRepeat, NORM);
140	            vlds(vreg1, src1Ptr, i * ElementsPerRepeat, NORM);
141	            Op::BinInstr(vreg2, vreg0, vreg1, preg);
142	            vsts(vreg2, dstPtr, i * ElementsPerRepeat, distValue, preg);
143	        }
144	    }
145	}
