147	template <typename Op, typename T, unsigned ElementsPerRepeat, unsigned BlockSizeElem>
148	PTO_INTERNAL void TBinOps_1D_PostUpdate(
149	    __ubuf__ T* dstPtr, __ubuf__ T* src0Ptr, __ubuf__ T* src1Ptr, unsigned validRows, unsigned validCols)
150	{
151	    uint16_t repeatTimes = CeilDivision(validRows * validCols, ElementsPerRepeat);
152	    __VEC_SCOPE__
153	    {
154	        RegTensor<T> vreg0_PU, vreg1_PU, vreg2_PU;
155	        MaskReg preg;
156	
157	        constexpr auto distValue =
158	            std::integral_constant<::DistVST, static_cast<::DistVST>(GetDistVst<T, DistVST::DIST_NORM>())>();
159	        unsigned sreg = validRows * validCols;
160	        for (uint16_t i = 0; i < (uint16_t)repeatTimes; ++i) {
161	            preg = CreatePredicate<T>(sreg);
162	            vlds(vreg0_PU, src0Ptr, ElementsPerRepeat, NORM, POST_UPDATE);
163	            vlds(vreg1_PU, src1Ptr, ElementsPerRepeat, NORM, POST_UPDATE);
164	            Op::BinInstr(vreg2_PU, vreg0_PU, vreg1_PU, preg);
165	            vsts(vreg2_PU, dstPtr, ElementsPerRepeat, distValue, preg, POST_UPDATE);
166	        }
167	    }
168	}
