170	template <
171	    typename Op, typename T, unsigned ElementsPerRepeat, unsigned BlockSizeElem, unsigned DstRowStride,
172	    unsigned Src0RowStride = DstRowStride, unsigned Src1RowStride = DstRowStride>
173	PTO_INTERNAL void TBinOps_2D_NoPostUpdate(
174	    __ubuf__ T* dstPtr, __ubuf__ T* src0Ptr, __ubuf__ T* src1Ptr, unsigned validRows, unsigned validCols)
175	{
176	    uint16_t repeatTimes = CeilDivision(validCols, ElementsPerRepeat);
177	
178	    __VEC_SCOPE__
179	    {
180	        RegTensor<T> vreg0, vreg1, vreg2;
181	        MaskReg preg;
182	        constexpr auto distValue =
183	            std::integral_constant<::DistVST, static_cast<::DistVST>(GetDistVst<T, DistVST::DIST_NORM>())>();
184	        for (uint16_t i = 0; i < (uint16_t)(validRows); ++i) {
185	            uint32_t sreg = (uint32_t)(validCols);
186	            for (uint16_t j = 0; j < (uint16_t)repeatTimes; ++j) {
187	                preg = CreatePredicate<T>(sreg);
188	                vlds(vreg0, src0Ptr, i * Src0RowStride + j * ElementsPerRepeat, NORM);
189	                vlds(vreg1, src1Ptr, i * Src1RowStride + j * ElementsPerRepeat, NORM);
190	                Op::BinInstr(vreg2, vreg0, vreg1, preg);
191	                vsts(vreg2, dstPtr, i * DstRowStride + j * ElementsPerRepeat, distValue, preg);
192	            }
193	        }
194	    }
195	}
