197	template <
198	    typename Op, typename T, unsigned ElementsPerRepeat, unsigned BlockSizeElem, unsigned DstRowStride,
199	    unsigned Src0RowStride = DstRowStride, unsigned Src1RowStride = DstRowStride>
200	PTO_INTERNAL void TBinOps_2D_PostUpdate_FullRepeats(
201	    __ubuf__ T* dstPtr, __ubuf__ T* src0Ptr, __ubuf__ T* src1Ptr, unsigned validRows, uint16_t fullRepeats)
202	{
203	    const int32_t rowAdvance = static_cast<int32_t>(fullRepeats) * static_cast<int32_t>(ElementsPerRepeat);
204	    const int32_t src0RowAdjust = static_cast<int32_t>(Src0RowStride) - rowAdvance;
205	    const int32_t src1RowAdjust = static_cast<int32_t>(Src1RowStride) - rowAdvance;
206	    const int32_t dstRowAdjust = static_cast<int32_t>(DstRowStride) - rowAdvance;
207	    __VEC_SCOPE__
208	    {
209	        RegTensor<T> vreg0_PU, vreg1_PU, vreg2_PU;
210	        MaskReg preg = PSetWithType<T>(PAT_ALL);
211	        constexpr auto distValue =
212	            std::integral_constant<::DistVST, static_cast<::DistVST>(GetDistVst<T, DistVST::DIST_NORM>())>();
213	        for (uint16_t i = 0; i < (uint16_t)(validRows); ++i) {
214	            for (uint16_t j = 0; j < (uint16_t)fullRepeats; ++j) {
215	                vlds(vreg0_PU, src0Ptr, ElementsPerRepeat, NORM, POST_UPDATE);
216	                vlds(vreg1_PU, src1Ptr, ElementsPerRepeat, NORM, POST_UPDATE);
217	                Op::BinInstr(vreg2_PU, vreg0_PU, vreg1_PU, preg);
218	                vsts(vreg2_PU, dstPtr, ElementsPerRepeat, distValue, preg, POST_UPDATE);
219	            }
220	            src0Ptr += src0RowAdjust;
221	            src1Ptr += src1RowAdjust;
222	            dstPtr += dstRowAdjust;
223	        }
224	    }
225	}
226	
227	template <
228	    typename Op, typename T, unsigned ElementsPerRepeat, unsigned BlockSizeElem, unsigned DstRowStride,
229	    unsigned Src0RowStride = DstRowStride, unsigned Src1RowStride = DstRowStride>
230	PTO_INTERNAL void TBinOps_2D_PostUpdate_FullRepeatsTail(
231	    __ubuf__ T* dstPtr, __ubuf__ T* src0Ptr, __ubuf__ T* src1Ptr, unsigned validRows, uint16_t fullRepeats,
232	    uint32_t tailCount)
233	{
234	    uint16_t repeatTimes = fullRepeats + 1;
235	    const int32_t rowAdvance = static_cast<int32_t>(repeatTimes) * static_cast<int32_t>(ElementsPerRepeat);
236	    const int32_t src0RowAdjust = static_cast<int32_t>(Src0RowStride) - rowAdvance;
237	    const int32_t src1RowAdjust = static_cast<int32_t>(Src1RowStride) - rowAdvance;
238	    const int32_t dstRowAdjust = static_cast<int32_t>(DstRowStride) - rowAdvance;
239	    __VEC_SCOPE__
240	    {
241	        RegTensor<T> vreg0_PU, vreg1_PU, vreg2_PU;
242	        MaskReg pregFull = PSetWithType<T>(PAT_ALL);
243	        MaskReg pregTail = CreatePredicate<T>(tailCount);
244	        constexpr auto distValue =
245	            std::integral_constant<::DistVST, static_cast<::DistVST>(GetDistVst<T, DistVST::DIST_NORM>())>();
246	        for (uint16_t i = 0; i < (uint16_t)(validRows); ++i) {
247	            for (uint16_t j = 0; j < (uint16_t)fullRepeats; ++j) {
248	                vlds(vreg0_PU, src0Ptr, ElementsPerRepeat, NORM, POST_UPDATE);
249	                vlds(vreg1_PU, src1Ptr, ElementsPerRepeat, NORM, POST_UPDATE);
250	                Op::BinInstr(vreg2_PU, vreg0_PU, vreg1_PU, pregFull);
251	                vsts(vreg2_PU, dstPtr, ElementsPerRepeat, distValue, pregFull, POST_UPDATE);
252	            }
253	            vlds(vreg0_PU, src0Ptr, ElementsPerRepeat, NORM, POST_UPDATE);
254	            vlds(vreg1_PU, src1Ptr, ElementsPerRepeat, NORM, POST_UPDATE);
255	            Op::BinInstr(vreg2_PU, vreg0_PU, vreg1_PU, pregTail);
256	            vsts(vreg2_PU, dstPtr, ElementsPerRepeat, distValue, pregTail, POST_UPDATE);
257	            src0Ptr += src0RowAdjust;
258	            src1Ptr += src1RowAdjust;
259	            dstPtr += dstRowAdjust;
260	        }
261	    }
262	}
263	
264	template <
265	    typename Op, typename T, unsigned ElementsPerRepeat, unsigned BlockSizeElem, unsigned DstRowStride,
266	    unsigned Src0RowStride = DstRowStride, unsigned Src1RowStride = DstRowStride>
267	PTO_INTERNAL void TBinOps_2D_PostUpdate(
268	    __ubuf__ T* dstPtr, __ubuf__ T* src0Ptr, __ubuf__ T* src1Ptr, unsigned validRows, unsigned validCols)
269	{
270	    uint16_t fullRepeats = validCols / ElementsPerRepeat;
271	    uint32_t tailCount = validCols - fullRepeats * ElementsPerRepeat;
272	    if (tailCount == 0) {
273	        TBinOps_2D_PostUpdate_FullRepeats<
274	            Op, T, ElementsPerRepeat, BlockSizeElem, DstRowStride, Src0RowStride, Src1RowStride>(
275	            dstPtr, src0Ptr, src1Ptr, validRows, fullRepeats);
276	    } else {
277	        TBinOps_2D_PostUpdate_FullRepeatsTail<
278	            Op, T, ElementsPerRepeat, BlockSizeElem, DstRowStride, Src0RowStride, Src1RowStride>(
279	            dstPtr, src0Ptr, src1Ptr, validRows, fullRepeats, tailCount);
280	    }
281	}
