283	template <
284	    typename Op, typename T, unsigned ElementsPerRepeat, unsigned BlockSizeElem, unsigned DstRowStride,
285	    unsigned Src0RowStride, unsigned Src1RowStride>
286	PTO_INTERNAL void TBinOp1DSwitch(
287	    __ubuf__ T* dst, __ubuf__ T* src0, __ubuf__ T* src1, unsigned validRows, unsigned validCols, VFImplKind version)
288	{
289	    switch (version) {
290	        case VFImplKind::VFIMPL_1D_NO_POST_UPDATE:
291	            TBinOps_1D_NoPostUpdate<Op, T, ElementsPerRepeat, BlockSizeElem>(dst, src0, src1, validRows, validCols);
292	            break;
293	        case VFImplKind::VFIMPL_2D_NO_POST_UPDATE:
294	            TBinOps_2D_NoPostUpdate<
295	                Op, T, ElementsPerRepeat, BlockSizeElem, DstRowStride, Src0RowStride, Src1RowStride>(
296	                dst, src0, src1, validRows, validCols);
297	            break;
298	        case VFImplKind::VFIMPL_2D_POST_UPDATE:
299	            TBinOps_2D_PostUpdate<Op, T, ElementsPerRepeat, BlockSizeElem, DstRowStride, Src0RowStride, Src1RowStride>(
300	                dst, src0, src1, validRows, validCols);
301	            break;
302	        case VFImplKind::VFIMPL_1D_POST_UPDATE:
303	        case VFImplKind::VFIMPL_DEFAULT:
304	        default:
305	            TBinOps_1D_PostUpdate<Op, T, ElementsPerRepeat, BlockSizeElem>(dst, src0, src1, validRows, validCols);
306	            break;
307	    }
308	}
309	
310	template <
311	    typename Op, typename T, unsigned ElementsPerRepeat, unsigned BlockSizeElem, unsigned DstRowStride,
312	    unsigned Src0RowStride, unsigned Src1RowStride>
313	PTO_INTERNAL void TBinOp2DSwitch(
314	    __ubuf__ T* dst, __ubuf__ T* src0, __ubuf__ T* src1, unsigned validRows, unsigned validCols, VFImplKind version)
315	{
316	    switch (version) {
317	        case VFImplKind::VFIMPL_1D_NO_POST_UPDATE:
318	        case VFImplKind::VFIMPL_2D_NO_POST_UPDATE:
319	            TBinOps_2D_NoPostUpdate<
320	                Op, T, ElementsPerRepeat, BlockSizeElem, DstRowStride, Src0RowStride, Src1RowStride>(
321	                dst, src0, src1, validRows, validCols);
322	            break;
323	        case VFImplKind::VFIMPL_1D_POST_UPDATE:
324	        case VFImplKind::VFIMPL_2D_POST_UPDATE:
325	            TBinOps_2D_PostUpdate<Op, T, ElementsPerRepeat, BlockSizeElem, DstRowStride, Src0RowStride, Src1RowStride>(
326	                dst, src0, src1, validRows, validCols);
327	            break;
328	        case VFImplKind::VFIMPL_DEFAULT:
329	        default:
330	            TBinOps_2D_NoPostUpdate<
331	                Op, T, ElementsPerRepeat, BlockSizeElem, DstRowStride, Src0RowStride, Src1RowStride>(
332	                dst, src0, src1, validRows, validCols);
333	            break;
334	    }
335	}
