337	// implement the template for tileshape of src0, src1 and dst are different
338	template <
339	    typename Op, typename TileDataDst, typename TileDataSrc0, typename TileDataSrc1, unsigned ElementsPerRepeat,
340	    unsigned BlockSizeElem>
341	PTO_INTERNAL void BinaryInstr(
342	    __ubuf__ typename TileDataDst::DType* dst, __ubuf__ typename TileDataSrc0::DType* src0,
343	    __ubuf__ typename TileDataSrc1::DType* src1, unsigned validRows, unsigned validCols, VFImplKind version)
344	{
345	    using T = typename TileDataDst::DType;
346	    constexpr unsigned dstRowStride = TileDataDst::RowStride;
347	    constexpr unsigned src0RowStride = TileDataSrc0::RowStride;
348	    constexpr unsigned src1RowStride = TileDataSrc1::RowStride;
349	    constexpr bool isContiguous =
350	        (((TileDataDst::ValidCol == TileDataDst::Cols) && (TileDataSrc0::ValidCol == TileDataSrc0::Cols)) &&
351	         (TileDataSrc1::ValidCol == TileDataSrc1::Cols)) ||
352	        ((TileDataDst::Rows == 1) && (TileDataSrc0::Rows == 1) && (TileDataSrc1::Rows == 1));
353	
354	    if constexpr (isContiguous) {
355	        TBinOp1DSwitch<Op, T, ElementsPerRepeat, BlockSizeElem, dstRowStride, src0RowStride, src1RowStride>(
356	            dst, src0, src1, validRows, validCols, version);
357	    } else {
358	        TBinOp2DSwitch<Op, T, ElementsPerRepeat, BlockSizeElem, dstRowStride, src0RowStride, src1RowStride>(
359	            dst, src0, src1, validRows, validCols, version);
360	    }
361	}
