363	#if defined(PTO_NPU_ARCH_A5) || defined(PTO_NPU_ARCH_A6)
364	template <bool Right, typename T>
365	PTO_INTERNAL void Int64ShiftRegs(
366	    vector_s32& dl, vector_s32& dh, vector_s32& sl, vector_s32& sh, vector_s32& cnt, MaskReg& mask)
367	{
368	    vector_s32 c32, cm, bias, norm, sixtyThree;
369	    vbr(bias, 32);
370	    vbr(sixtyThree, 63);
371	    vand((vector_u32&)norm, (vector_u32&)cnt, (vector_u32&)sixtyThree, mask, MODE_ZEROING);
372	    vadds(c32, norm, 32, mask);
373	    vsub(cm, bias, norm, mask);
374	    MaskReg lt32, ge32;
375	    vcmp_lt(lt32, norm, bias, mask);
376	    vcmp_ge(ge32, norm, bias, mask);
377	    vector_s32 lo0, hi0, lo1, hi1, t;
378	    if constexpr (!Right) {
379	        vshl(lo0, sl, norm, mask, MODE_ZEROING);
380	        vshl(hi0, sh, norm, mask, MODE_ZEROING);
381	        vshr(t, sl, cm, mask, MODE_ZEROING);
382	        vor(hi0, hi0, t, mask);
383	        vsub(c32, norm, bias, mask);
384	        vshl(hi1, sl, c32, mask, MODE_ZEROING);
385	        vbr(lo1, 0);
386	    } else {
387	        if constexpr (std::is_same_v<T, int64_t>)
388	            vshr(hi0, sh, norm, mask, MODE_ZEROING);
389	        else
390	            vshr((vector_u32&)hi0, (vector_u32&)sh, norm, mask, MODE_ZEROING);
391	        vshr((vector_u32&)lo0, (vector_u32&)sl, norm, mask, MODE_ZEROING);
392	        vshl(t, sh, cm, mask, MODE_ZEROING);
393	        vor(lo0, lo0, t, mask);
394	        vsub(c32, norm, bias, mask);
395	        if constexpr (std::is_same_v<T, int64_t>) {
396	            vshr(lo1, sh, c32, mask, MODE_ZEROING);
397	            vshrs(hi1, sh, 31, mask, MODE_ZEROING);
398	        } else {
399	            vshr((vector_u32&)lo1, (vector_u32&)sh, c32, mask, MODE_ZEROING);
400	            vbr(hi1, 0);
401	        }
402	    }
403	    vsel(dl, lo0, lo1, lt32);
404	    vsel(dh, hi0, hi1, lt32);
405	}
