407	template <Int64Op Op, typename T>
408	PTO_INTERNAL void Int64MinMax(
409	    vector_s32& dstLow, vector_s32& dstHigh, vector_s32& src0Low, vector_s32& src0High, vector_s32& src1Low,
410	    vector_s32& src1High, MaskReg& mask)
411	{
412	    MaskReg highEq, lowCmp, highCmp, selectMask;
413	    vcmp_eq(highEq, src0High, src1High, mask);
414	    if constexpr (Op == Int64Op::Max) {
415	        vcmp_gt(lowCmp, (vector_u32&)src0Low, (vector_u32&)src1Low, mask);
416	        if constexpr (std::is_same_v<T, int64_t>)
417	            vcmp_gt(highCmp, src0High, src1High, mask);
418	        else
419	            vcmp_gt(highCmp, (vector_u32&)src0High, (vector_u32&)src1High, mask);
420	    } else {
421	        vcmp_lt(lowCmp, (vector_u32&)src0Low, (vector_u32&)src1Low, mask);
422	        if constexpr (std::is_same_v<T, int64_t>)
423	            vcmp_lt(highCmp, src0High, src1High, mask);
424	        else
425	            vcmp_lt(highCmp, (vector_u32&)src0High, (vector_u32&)src1High, mask);
426	    }
427	    psel(selectMask, lowCmp, highCmp, highEq);
428	    vsel(dstLow, src0Low, src1Low, selectMask);
429	    vsel(dstHigh, src0High, src1High, selectMask);
430	}
431	
432	template <Int64Op Op, typename T>
433	PTO_INTERNAL void Int64BinaryCalcRegs(
434	    vector_s32& dstLow, vector_s32& dstHigh, vector_s32& src0Low, vector_s32& src0High, vector_s32& src1Low,
435	    vector_s32& src1High, MaskReg& mask)
436	{
437	    MaskReg carry, carryOut;
438	    if constexpr (Op == Int64Op::Add) {
439	        vaddc(carry, dstLow, src0Low, src1Low, mask);
440	        vaddcs(carryOut, dstHigh, src0High, src1High, carry, mask);
441	    } else if constexpr (Op == Int64Op::Sub) {
442	        vsubc(carry, dstLow, src0Low, src1Low, mask);
443	        vsubcs(carryOut, dstHigh, src0High, src1High, carry, mask);
444	    } else if constexpr (Op == Int64Op::Mul) {
445	        vmull((vector_u32&)dstLow, (vector_u32&)dstHigh, (vector_u32&)src0Low, (vector_u32&)src1Low, mask);
446	        vmula(dstHigh, src0Low, src1High, mask, MODE_ZEROING);
447	        vmula(dstHigh, src0High, src1Low, mask, MODE_ZEROING);
448	    } else if constexpr (Op == Int64Op::Shl || Op == Int64Op::Shr) {
449	        Int64ShiftRegs<Op == Int64Op::Shr, T>(dstLow, dstHigh, src0Low, src0High, src1Low, mask);
450	    } else if constexpr (Op == Int64Op::And) {
451	        vand((vector_u32&)dstLow, (vector_u32&)src0Low, (vector_u32&)src1Low, mask, MODE_ZEROING);
452	        vand((vector_u32&)dstHigh, (vector_u32&)src0High, (vector_u32&)src1High, mask, MODE_ZEROING);
453	    } else if constexpr (Op == Int64Op::Or) {
454	        vor((vector_u32&)dstLow, (vector_u32&)src0Low, (vector_u32&)src1Low, mask, MODE_ZEROING);
455	        vor((vector_u32&)dstHigh, (vector_u32&)src0High, (vector_u32&)src1High, mask, MODE_ZEROING);
456	    } else if constexpr (Op == Int64Op::Xor) {
457	        vxor((vector_u32&)dstLow, (vector_u32&)src0Low, (vector_u32&)src1Low, mask, MODE_ZEROING);
458	        vxor((vector_u32&)dstHigh, (vector_u32&)src0High, (vector_u32&)src1High, mask, MODE_ZEROING);
459	    } else {
460	        Int64MinMax<Op, T>(dstLow, dstHigh, src0Low, src0High, src1Low, src1High, mask);
461	    }
462	}
463	
464	template <Int64Op Op, typename T, unsigned DstCols, unsigned Src0Cols, unsigned Src1Cols>
465	PTO_INTERNAL void Int64BinaryRepeat(
466	    __ubuf__ T* dst, __ubuf__ T* src0, __ubuf__ T* src1, uint16_t row, uint32_t colOffset, MaskReg& mask)
467	{
468	    vector_s32 dstLow, dstHigh, src0Low, src0High, src1Low, src1High, half0, half1;
469	    MaskReg lowMask, highMask;
470	    uint32_t src0Offset = (row * Src0Cols + colOffset) * 2;
471	    uint32_t src1Offset = (row * Src1Cols + colOffset) * 2;
472	    uint32_t dstOffset = (row * DstCols + colOffset) * 2;
473	    vlds(src0Low, src0High, (__ubuf__ int32_t*)src0, src0Offset, DINTLV_B32);
474	    vlds(src1Low, src1High, (__ubuf__ int32_t*)src1, src1Offset, DINTLV_B32);
475	    Int64BinaryCalcRegs<Op, T>(dstLow, dstHigh, src0Low, src0High, src1Low, src1High, mask);
476	    pintlv_b32(lowMask, highMask, mask, mask);
477	    vintlv(half0, half1, dstLow, dstHigh);
478	    vsts(half0, (__ubuf__ int32_t*)dst, dstOffset, NORM_B32, lowMask);
479	    vsts(half1, (__ubuf__ int32_t*)dst, dstOffset + CCE_VL / sizeof(int32_t), NORM_B32, highMask);
480	}
481	
482	template <Int64Op Op, typename T, unsigned DstCols, unsigned Src0Cols, unsigned Src1Cols>
483	PTO_INTERNAL void Int64Binary(
484	    __ubuf__ T* dst, __ubuf__ T* src0, __ubuf__ T* src1, unsigned validRows, unsigned validCols)
485	{
486	    constexpr unsigned elementsPerRepeat = CCE_VL * 2 / sizeof(T);
487	    __VEC_SCOPE__
488	    {
489	        uint16_t rowCount = validRows;
490	        uint16_t colRepeats = CeilDivision(validCols, elementsPerRepeat);
491	        for (uint16_t row = 0; row < rowCount; ++row) {
492	            uint32_t sreg = validCols;
493	            for (uint16_t colRepeat = 0; colRepeat < colRepeats; ++colRepeat) {
494	                MaskReg preg = CreatePredicate<uint32_t>(sreg);
495	                Int64BinaryRepeat<Op, T, DstCols, Src0Cols, Src1Cols>(
496	                    dst, src0, src1, row, colRepeat * elementsPerRepeat, preg);
497	            }
498	        }
499	    }
500	}
501	#else
502	template <Int64Op Op, typename T, unsigned DstCols, unsigned Src0Cols, unsigned Src1Cols>
503	PTO_INTERNAL void Int64Binary(
504	    __ubuf__ T* dst, __ubuf__ T* src0, __ubuf__ T* src1, unsigned validRows, unsigned validCols);
505	#endif
506	} // namespace pto
507	
508	#endif
