25	template <typename Op, typename T, unsigned nRepeatElem>
26	PTO_INTERNAL void TUnaryOps_1D_NoPostUpdate(__ubuf__ T* dst, __ubuf__ T* src, unsigned validRow, unsigned validCol)
27	{
28	    uint16_t repeatTimes = CeilDivision(validRow * validCol, nRepeatElem);
29	    __VEC_SCOPE__
30	    {
31	        RegTensor<T> srcReg;
32	        RegTensor<T> dstReg;
33	        unsigned sReg = validRow * validCol;
34	        MaskReg pReg;
35	        constexpr auto distValue =
36	            std::integral_constant<::DistVST, static_cast<::DistVST>(GetDistVst<T, DistVST::DIST_NORM>())>();
37	        for (uint16_t i = 0; i < repeatTimes; ++i) {
38	            pReg = CreatePredicate<T>(sReg);
39	            vlds(srcReg, src, i * nRepeatElem, NORM);
40	            Op::UnaryInstr(dstReg, srcReg, pReg);
41	            vsts(dstReg, dst, i * nRepeatElem, distValue, pReg);
42	        }
43	    }
44	}
45	
46	template <typename Op, typename T, unsigned nRepeatElem>
47	PTO_INTERNAL void TUnaryOps_1D_PostUpdate(__ubuf__ T* dst, __ubuf__ T* src, unsigned validRow, unsigned validCol)
48	{
49	    uint16_t repeatTimes = CeilDivision(validRow * validCol, nRepeatElem);
50	    __VEC_SCOPE__
51	    {
52	        RegTensor<T> srcReg;
53	        RegTensor<T> dstReg;
54	        MaskReg pReg;
55	        unsigned sReg = validRow * validCol;
56	        constexpr auto distValue =
57	            std::integral_constant<::DistVST, static_cast<::DistVST>(GetDistVst<T, DistVST::DIST_NORM>())>();
58	        for (uint16_t i = 0; i < repeatTimes; ++i) {
59	            pReg = CreatePredicate<T>(sReg);
60	            vlds(srcReg, src, nRepeatElem, NORM, POST_UPDATE);
61	            Op::UnaryInstr(dstReg, srcReg, pReg);
62	            vsts(dstReg, dst, nRepeatElem, distValue, pReg, POST_UPDATE);
63	        }
64	    }
65	}
66	
67	template <typename Op, typename T, unsigned DstRowStride, unsigned SrcRowStride, unsigned nRepeatElem>
68	PTO_INTERNAL void TUnaryOps_2D(__ubuf__ T* dst, __ubuf__ T* src, unsigned validRow, unsigned validCol)
69	{
70	    uint16_t repeatTimes = CeilDivision(validCol, nRepeatElem);
71	    __VEC_SCOPE__
72	    {
73	        RegTensor<T> srcReg;
74	        RegTensor<T> dstReg;
75	        MaskReg pReg;
76	        unsigned sReg;
77	        constexpr auto distValue =
78	            std::integral_constant<::DistVST, static_cast<::DistVST>(GetDistVst<T, DistVST::DIST_NORM>())>();
79	        for (uint16_t i = 0; i < (uint16_t)validRow; ++i) {
80	            sReg = validCol;
81	            for (uint16_t j = 0; j < repeatTimes; ++j) {
82	                pReg = CreatePredicate<T>(sReg);
83	                vlds(srcReg, src, i * SrcRowStride + j * nRepeatElem, NORM);
84	                Op::UnaryInstr(dstReg, srcReg, pReg);
85	                vsts(dstReg, dst, i * DstRowStride + j * nRepeatElem, distValue, pReg);
86	            }
87	        }
88	    }
89	}
90	
91	template <typename Op, typename T, typename DstTile, typename SrcTile, unsigned nRepeatElem>
92	PTO_INTERNAL void TUnaryOps_1D_Switch(
93	    __ubuf__ T* dst, __ubuf__ T* src, unsigned validRow, unsigned validCol, VFImplKind version)
94	{
95	    switch (version) {
96	        case VFImplKind::VFIMPL_1D_NO_POST_UPDATE: {
97	            TUnaryOps_1D_NoPostUpdate<Op, T, nRepeatElem>(dst, src, validRow, validCol);
98	            break;
99	        }
100	        case VFImplKind::VFIMPL_2D_POST_UPDATE:
101	        case VFImplKind::VFIMPL_2D_NO_POST_UPDATE: {
102	            TUnaryOps_2D<Op, T, DstTile::RowStride, SrcTile::RowStride, nRepeatElem>(dst, src, validRow, validCol);
103	            break;
104	        }
105	        default: {
106	            TUnaryOps_1D_PostUpdate<Op, T, nRepeatElem>(dst, src, validRow, validCol);
107	            break;
108	        }
109	    }
110	}
111	
112	template <typename DstTile, typename SrcTile, typename Op>
113	PTO_INTERNAL void TUnaryOp(
114	    __ubuf__ typename DstTile::DType* dst, __ubuf__ typename SrcTile::DType* src, unsigned validRow, unsigned validCol,
115	    VFImplKind version)
116	{
117	    using T = typename DstTile::DType;
118	    constexpr unsigned nRepeatElem = CCE_VL / sizeof(T);
119	    if constexpr (
120	        ((DstTile::ValidCol == DstTile::Cols) && (SrcTile::ValidCol == SrcTile::Cols)) ||
121	        ((DstTile::Rows == 1) && (SrcTile::Rows == 1))) {
122	        TUnaryOps_1D_Switch<Op, T, DstTile, SrcTile, nRepeatElem>(dst, src, validRow, validCol, version);
123	    } else {
124	        TUnaryOps_2D<Op, T, DstTile::RowStride, SrcTile::RowStride, nRepeatElem>(dst, src, validRow, validCol);
125	    }
126	}
