128	template <typename DstTile, typename SrcTile, bool needDataTypeCheck = true>
129	PTO_INTERNAL void TUnaryCheck()
130	{
131	    static_assert(DstTile::isRowMajor && SrcTile::isRowMajor, "TUnaryOp: Not supported Layout type");
132	    static_assert(
133	        DstTile::Loc == TileType::Vec && SrcTile::Loc == TileType::Vec,
134	        "TUnaryOp: TileType of src and dst tiles must be TileType::Vec.");
135	    static_assert(
136	        DstTile::ValidCol <= DstTile::Cols,
137	        "TUnaryOp: Number of dst's valid columns must not be greater than number of tile columns.");
138	    static_assert(
139	        DstTile::ValidRow <= DstTile::Rows,
140	        "TUnaryOp: Number of dst's valid rows must not be greater than number of tile rows.");
141	    static_assert(
142	        SrcTile::ValidCol <= SrcTile::Cols,
143	        "TUnaryOp: Number of src's valid columns must not be greater than number of tile columns.");
144	    static_assert(
145	        SrcTile::ValidRow <= SrcTile::Rows,
146	        "TUnaryOp: Number of src's valid rows must not be greater than number of tile rows.");
147	    static_assert(
148	        std::is_same_v<typename DstTile::DType, typename SrcTile::DType>,
149	        "TUnaryOp: The data type of dst must be consistent with of src");
150	    static_assert(
151	        !needDataTypeCheck || std::is_same_v<typename DstTile::DType, float32_t> ||
152	            std::is_same_v<typename DstTile::DType, float> || std::is_same_v<typename DstTile::DType, float16_t> ||
153	            std::is_same_v<typename DstTile::DType, half>,
154	        "TUnaryOp: Invalid data type.");
155	}
