158	template <Int64Op Op, typename T, unsigned DstCols, unsigned SrcCols>
159	PTO_INTERNAL void Int64UnaryRepeat(__ubuf__ T* dst, __ubuf__ T* src, uint16_t row, uint32_t colOffset, MaskReg& mask)
160	{
161	    vector_s32 dstLow, dstHigh, srcLow, srcHigh, half0, half1;
162	    MaskReg lowMask, highMask;
163	    uint32_t srcOffset = (row * SrcCols + colOffset) * 2;
164	    uint32_t dstOffset = (row * DstCols + colOffset) * 2;
165	    vlds(srcLow, srcHigh, (__ubuf__ int32_t*)src, srcOffset, DINTLV_B32);
166	    if constexpr (Op == Int64Op::Not) {
167	        vnot((vector_u32&)dstLow, (vector_u32&)srcLow, mask, MODE_ZEROING);
168	        vnot((vector_u32&)dstHigh, (vector_u32&)srcHigh, mask, MODE_ZEROING);
169	    } else {
170	        Int64AbsRegs(dstLow, dstHigh, srcLow, srcHigh, mask);
171	    }
172	    pintlv_b32(lowMask, highMask, mask, mask);
173	    vintlv(half0, half1, dstLow, dstHigh);
174	    vsts(half0, (__ubuf__ int32_t*)dst, dstOffset, NORM_B32, lowMask);
175	    vsts(half1, (__ubuf__ int32_t*)dst, dstOffset + CCE_VL / sizeof(int32_t), NORM_B32, highMask);
176	}
