178	template <Int64Op Op, typename T, unsigned DstCols, unsigned SrcCols>
179	PTO_INTERNAL void Int64Unary(__ubuf__ T* dst, __ubuf__ T* src, unsigned validRows, unsigned validCols)
180	{
181	    constexpr unsigned elementsPerRepeat = CCE_VL * 2 / sizeof(T);
182	    __VEC_SCOPE__
183	    {
184	        uint16_t rowCount = validRows;
185	        uint16_t colRepeats = CeilDivision(validCols, elementsPerRepeat);
186	        for (uint16_t row = 0; row < rowCount; ++row) {
187	            uint32_t sreg = validCols;
188	            for (uint16_t colRepeat = 0; colRepeat < colRepeats; ++colRepeat) {
189	                MaskReg preg = CreatePredicate<uint32_t>(sreg);
190	                Int64UnaryRepeat<Op, T, DstCols, SrcCols>(dst, src, row, colRepeat * elementsPerRepeat, preg);
191	            }
192	        }
193	    }
194	}
