/* TLOG */
template <LogAlgorithm PrecisionType, typename T>
struct LogOp {
    PTO_INTERNAL static void UnaryInstr(RegTensor<T>& dstReg, RegTensor<T>& srcReg, MaskReg& pReg)
    {
        if constexpr (
