#include <pto/pto-inst.hpp>
#include <pto/common/constants.hpp>
#include "acl/acl.h"

using namespace pto;

template <typename T, int kTRows_, int kTCols_, int vRows, int vCols>
__global__ AICORE void runTXor(__gm__ T __out__* out, __gm__ T __in__* src0, __gm__ T __in__* src1)
{
    using DynShapeDim5 = Shape<1, 1, 1, vRows, vCols>;
    using DynStridDim5 = pto::Stride<1, 1, 1, vCols, 1>;
    using GlobalData = GlobalTensor<T, DynShapeDim5, DynStridDim5>;
    using TileData = Tile<TileType::Vec, T, kTRows_, kTCols_, BLayout::RowMajor, -1, -1>;
    TileData src0Tile(vRows, vCols);
    TileData src1Tile(vRows, vCols);
    TileData dstTile(vRows, vCols);
    TASSIGN(src0Tile, 0x0);
    TASSIGN(src1Tile, 0x10000);
    TASSIGN(dstTile, 0x20000);

    GlobalData src0Global(src0);
    GlobalData src1Global(src1);
    GlobalData dstGlobal(out);

    Event<Op::TLOAD, Op::TXOR> event0;
    Event<Op::TXOR, Op::TSTORE_VEC> event1;

    TLOAD(src0Tile, src0Global);
    event0 = TLOAD(src1Tile, src1Global);
    event1 = TXOR(dstTile, src0Tile, src1Tile, dstTile /*not used*/, event0);
    TSTORE(dstGlobal, dstTile, event1);
    out = dstGlobal.data();
}

template <typename T, int kTRows_, int kTCols_, int vRows, int vCols>
void LaunchTXor(T* out, T* src0, T* src1, void* stream)
{
    runTXor<T, kTRows_, kTCols_, vRows, vCols><<<1, nullptr, stream>>>(out, src0, src1);
}

template void LaunchTXor<uint16_t, 64, 64, 64, 64>(uint16_t* out, uint16_t* src0, uint16_t* src1, void* stream);
template void LaunchTXor<uint16_t, 64, 64, 63, 63>(uint16_t* out, uint16_t* src0, uint16_t* src1, void* stream);
template void LaunchTXor<uint16_t, 1, 16384, 1, 16384>(uint16_t* out, uint16_t* src0, uint16_t* src1, void* stream);
template void LaunchTXor<uint16_t, 2048, 16, 2048, 16>(uint16_t* out, uint16_t* src0, uint16_t* src1, void* stream);
template void LaunchTXor<uint8_t, 32, 32, 32, 32>(uint8_t* out, uint8_t* src0, uint8_t* src1, void* stream);
