199	        sizeof(T) == sizeof(uint32_t), uint32_t, std::conditional_t<sizeof(T) == sizeof(uint16_t), uint16_t, uint8_t>>;
200	
201	    PTO_INTERNAL static constexpr Type GetPaddingMin()
202	    {
203	        if constexpr (std::is_same_v<T, float>) {
204	            return (Type)0xff800000UL;
205	        } else if constexpr (std::is_same_v<T, half>) {
206	            return (Type)0xfc00UL;
207	        } else if constexpr (std::is_same_v<T, bfloat16_t>) {
208	            return (Type)0xff80UL;
209	        } else if constexpr (std::is_same_v<T, int32_t>) {
210	            return (Type)0x80000000UL;
211	        } else if constexpr (std::is_same_v<T, int16_t>) {
212	            return (Type)0x8000UL;
213	        } else if constexpr (std::is_same_v<T, int8_t>) {
214	            return (Type)0x80UL;
215	        } else {
216	            return (Type)0;
217	        }
218	    }
219	
220	    PTO_INTERNAL static constexpr Type GetPaddingMax()
221	    {
222	        if constexpr (std::is_same_v<T, float>) {
223	            return (Type)0x7f800000UL;
224	        } else if constexpr (std::is_same_v<T, half>) {
225	            return (Type)0x7c00UL;
226	        } else if constexpr (std::is_same_v<T, bfloat16_t>) {
227	            return (Type)0x7f80UL;
228	        } else if constexpr (std::is_same_v<T, int32_t>) {
229	            return (Type)0x7fffffffUL;
230	        } else if constexpr (std::is_same_v<T, int16_t>) {
231	            return (Type)0x7fffUL;
232	        } else if constexpr (std::is_same_v<T, int8_t>) {
233	            return (Type)0x7fUL;
234	        } else {
235	            return (Type)(~(Type)0);
236	        }
237	    }
238	
239	    static constexpr Type Null = (Type)0;
240	    static constexpr Type Zero = (Type)0;
241	    static constexpr Type Min = GetPaddingMin();
242	    static constexpr Type Max = GetPaddingMax();
243	};
