22	#if defined(PTO_NPU_ARCH_A5) || defined(PTO_NPU_ARCH_A6)
23	template <Int64Op Op, typename T>
24	PTO_INTERNAL void Int64ScalarCalcRegs(
25	    vector_s32& dstLow, vector_s32& dstHigh, vector_s32& srcLow, vector_s32& srcHigh, vector_s32& scalarLow,
26	    vector_s32& scalarHigh, uint64_t scalarBits, MaskReg& mask)
27	{
28	    MaskReg carry;
29	    MaskReg carryOut;
30	    if constexpr (Op == Int64Op::Add) {
31	        vaddc(carry, dstLow, srcLow, scalarLow, mask);
32	        vaddcs(carryOut, dstHigh, srcHigh, scalarHigh, carry, mask);
33	    } else if constexpr (Op == Int64Op::Sub) {
34	        vsubc(carry, dstLow, srcLow, scalarLow, mask);
35	        vsubcs(carryOut, dstHigh, srcHigh, scalarHigh, carry, mask);
36	    } else if constexpr (Op == Int64Op::Mul) {
37	        vmull((vector_u32&)dstLow, (vector_u32&)dstHigh, (vector_u32&)srcLow, (vector_u32&)scalarLow, mask);
38	        vmula(dstHigh, srcLow, scalarHigh, mask, MODE_ZEROING);
39	        vmula(dstHigh, srcHigh, scalarLow, mask, MODE_ZEROING);
40	    } else if constexpr (Op == Int64Op::Shl) {
41	        vbr(scalarLow, static_cast<int32_t>(scalarBits));
42	        Int64ShiftRegs<false, T>(dstLow, dstHigh, srcLow, srcHigh, scalarLow, mask);
43	    } else if constexpr (Op == Int64Op::Shr) {
44	        vbr(scalarLow, static_cast<int32_t>(scalarBits));
45	        Int64ShiftRegs<true, T>(dstLow, dstHigh, srcLow, srcHigh, scalarLow, mask);
46	    } else if constexpr (Op == Int64Op::And) {
47	        vand((vector_u32&)dstLow, (vector_u32&)srcLow, (vector_u32&)scalarLow, mask, MODE_ZEROING);
48	        vand((vector_u32&)dstHigh, (vector_u32&)srcHigh, (vector_u32&)scalarHigh, mask, MODE_ZEROING);
49	    } else if constexpr (Op == Int64Op::Or) {
50	        vor((vector_u32&)dstLow, (vector_u32&)srcLow, (vector_u32&)scalarLow, mask, MODE_ZEROING);
51	        vor((vector_u32&)dstHigh, (vector_u32&)srcHigh, (vector_u32&)scalarHigh, mask, MODE_ZEROING);
52	    } else if constexpr (Op == Int64Op::Xor) {
53	        vxor((vector_u32&)dstLow, (vector_u32&)srcLow, (vector_u32&)scalarLow, mask, MODE_ZEROING);
54	        vxor((vector_u32&)dstHigh, (vector_u32&)srcHigh, (vector_u32&)scalarHigh, mask, MODE_ZEROING);
55	    } else {
56	        Int64MinMax<Op, T>(dstLow, dstHigh, srcLow, srcHigh, scalarLow, scalarHigh, mask);
57	    }
58	}
59	
60	template <Int64Op Op, typename T, unsigned DstCols, unsigned SrcCols>
61	PTO_INTERNAL void Int64ScalarRepeat(
62	    __ubuf__ T* dst, __ubuf__ T* src, uint16_t row, uint32_t colOffset, vector_s32& scalarLow, vector_s32& scalarHigh,
63	    uint64_t scalarBits, MaskReg& mask)
64	{
65	    vector_s32 dstLow, dstHigh, srcLow, srcHigh, half0, half1;
66	    MaskReg lowMask, highMask;
67	    uint32_t srcOffset = (row * SrcCols + colOffset) * 2;
68	    uint32_t dstOffset = (row * DstCols + colOffset) * 2;
69	    vlds(srcLow, srcHigh, (__ubuf__ int32_t*)src, srcOffset, DINTLV_B32);
70	    Int64ScalarCalcRegs<Op, T>(dstLow, dstHigh, srcLow, srcHigh, scalarLow, scalarHigh, scalarBits, mask);
71	    pintlv_b32(lowMask, highMask, mask, mask);
72	    vintlv(half0, half1, dstLow, dstHigh);
73	    vsts(half0, (__ubuf__ int32_t*)dst, dstOffset, NORM_B32, lowMask);
74	    vsts(half1, (__ubuf__ int32_t*)dst, dstOffset + CCE_VL / sizeof(int32_t), NORM_B32, highMask);
75	}
76	
77	template <Int64Op Op, typename T, unsigned DstCols, unsigned SrcCols>
78	PTO_INTERNAL void Int64Scalar(__ubuf__ T* dst, __ubuf__ T* src, T scalar, unsigned validRows, unsigned validCols)
79	{
80	    constexpr unsigned elementsPerRepeat = CCE_VL * 2 / sizeof(T);
81	    __VEC_SCOPE__
82	    {
83	        vector_s32 scalarLow, scalarHigh;
84	        uint64_t scalarBits = static_cast<uint64_t>(scalar);
85	        vbr(scalarLow, static_cast<int32_t>(scalarBits));
86	        vbr(scalarHigh, static_cast<int32_t>(scalarBits >> 32));
87	        uint16_t rowCount = validRows;
88	        uint16_t colRepeats = CeilDivision(validCols, elementsPerRepeat);
89	        for (uint16_t row = 0; row < rowCount; ++row) {
90	            uint32_t sreg = validCols;
91	            for (uint16_t colRepeat = 0; colRepeat < colRepeats; ++colRepeat) {
92	                MaskReg preg = CreatePredicate<uint32_t>(sreg);
93	                Int64ScalarRepeat<Op, T, DstCols, SrcCols>(
94	                    dst, src, row, colRepeat * elementsPerRepeat, scalarLow, scalarHigh, scalarBits, preg);
95	            }
96	        }
97	    }
98	}
